import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Kernel 日报 2026-11-17","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/17.md","filePath":"notes/kernel-digest/2026/11/17.md"}'),n={name:"notes/kernel-digest/2026/11/17.md"};function l(i,e,d,c,s,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-17" tabindex="-1">Kernel 日报 2026-11-17 <a class="header-anchor" href="#kernel-日报-2026-11-17" aria-label="Permalink to &quot;Kernel 日报 2026-11-17&quot;">​</a></h1><blockquote><p>生成时间：2026-11-17T02:09:10Z｜共 40 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-17 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_11598d36da13-·-a-new-generation-of-futexes" tabindex="-1"><code>11598d36da13</code> · <a href="https://lwn.net/Articles/1102988/" target="_blank" rel="noreferrer">[$] A new generation of futexes</a> <a class="header-anchor" href="#_11598d36da13-·-a-new-generation-of-futexes" aria-label="Permalink to &quot;`11598d36da13` · [[$] A new generation of futexes](https://lwn.net/Articles/1102988/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>futex 是内核中为用户空间快速 mutex 提供支持的子系统，但其性能仍不能满足部分用户需求，且多年来实现日趋复杂，目前存在两种基本变体。Suleiman Souhlal 发布了新的补丁系列，引入第三种 futex 类别 &quot;futex PING&quot;（priority inheritance next generation），以追求更快的 futex 性能。</p><blockquote><p><strong>学习价值</strong>：futex 是理解用户空间同步原语与内核交互的经典案例，本文展示了同步子系统演进中性能与复杂度的权衡，对学习内核锁机制很有价值。</p></blockquote><h3 id="_9253c4f7ee89-·-patch-v2-0-4-arm64-add-pud-thp-support-for-dax-and-pfnmap" tabindex="-1"><code>9253c4f7ee89</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-1-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 0/4] arm64: Add PUD THP support for DAX and pfnmap</a> <a class="header-anchor" href="#_9253c4f7ee89-·-patch-v2-0-4-arm64-add-pud-thp-support-for-dax-and-pfnmap" aria-label="Permalink to &quot;`9253c4f7ee89` · [[PATCH v2 0/4] arm64: Add PUD THP support for DAX and pfnmap](https://lore.kernel.org/all/20261117020237.4037980-1-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm｜内存管理</em></p><p>该补丁系列为 arm64 添加 PUD 级别透明大页（THP）支持，使 DAX 和 pfnmap 场景可使用 1GB 级别的大页映射。系列包括将 x86 和 riscv 中相同的 pudp_invalidate() 实现移到通用位置、简化 pmd_special/pmd_mkspecial、添加 spurious PUD fault 修复及 PUD 页表辅助函数并选中 HAVE_ARCH_TRANSPARENT_HUGEPAGE_PUD。</p><blockquote><p><strong>学习价值</strong>：深入涉及 arm64 页表层次、THP、DAX 与 pfnmap 的交互，是学习架构级 mm 特性实现的高质量材料。</p></blockquote><h3 id="a58e6cf40d19-·-patch-v3-0-5-rust-sync-add-waitqueue-infrastructure" tabindex="-1"><code>a58e6cf40d19</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 0/5] rust: sync: add WaitQueue infrastructure</a> <a class="header-anchor" href="#a58e6cf40d19-·-patch-v3-0-5-rust-sync-add-waitqueue-infrastructure" aria-label="Permalink to &quot;`a58e6cf40d19` · [[PATCH v3 0/5] rust: sync: add WaitQueue infrastructure](https://lore.kernel.org/all/20261117001507.1611984-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列新增封装 struct wait_queue_head 的 WaitQueue 抽象，提供接受条件闭包的 wait_event() 风格方法。动机来自后续 DRM 补丁（驱动 unbind 时等待 in-flight 文件关闭操作）以及 Tyr 驱动的 CSF firmware 响应等待需求，同时将 CondVar 转换为基于 WaitQueue 实现并去除重复代码。</p><blockquote><p><strong>学习价值</strong>：展示了内核抽象 API 的设计如何由真实驱动需求驱动，cover letter 中对动机和依赖关系的说明对理解补丁系列组织方式很有帮助。</p></blockquote><h3 id="b75a2965c720-·-patch-v22-0-5-rust-add-ownable-trait-and-owned-type" tabindex="-1"><code>b75a2965c720</code> · <a href="https://lore.kernel.org/all/20261116-unique-ref-v22-0-12029383206d@kernel.org/" target="_blank" rel="noreferrer">[PATCH v22 0/5] rust: add <code>Ownable</code> trait and <code>Owned</code> type</a> <a class="header-anchor" href="#b75a2965c720-·-patch-v22-0-5-rust-add-ownable-trait-and-owned-type" aria-label="Permalink to &quot;`b75a2965c720` · [[PATCH v22 0/5] rust: add `Ownable` trait and `Owned` type](https://lore.kernel.org/all/20261116-unique-ref-v22-0-12029383206d@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列新增 Ownable trait 和 Owned 类型，用于自定义分配和销毁方式的类型（尤其适用于 C 侧类型），保证任一时刻最多存在一个 Owned&lt;T&gt;。同时将 RefCounted trait 从 AlwaysRefCounted 中拆分，使类型可与 ARef 配合而不允许 &amp;T 到 ARef&lt;T&gt; 的转换，并为 Owned 实现 ForeignOwnable。</p><blockquote><p><strong>学习价值</strong>：是研究 Rust 内核引用计数与所有权模型演进的优秀材料，trait 拆分决策体现了 API 设计的权衡思路。</p></blockquote><h3 id="_1bc264edce5d-·-patch-v5-0-4-arm64-mm-convert-pgtable-read-once-as-pxdp-get" tabindex="-1"><code>1bc264edce5d</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-1-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 0/4] arm64/mm: Convert pgtable READ_ONCE() as pxdp_get()</a> <a class="header-anchor" href="#_1bc264edce5d-·-patch-v5-0-4-arm64-mm-convert-pgtable-read-once-as-pxdp-get" aria-label="Permalink to &quot;`1bc264edce5d` · [[PATCH V5 0/4] arm64/mm: Convert pgtable READ_ONCE() as pxdp_get()](https://lore.kernel.org/all/20261117012758.3814093-1-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm｜网络</em></p><p>本系列将页表项的 READ_ONCE() 访问统一改经级别专用的通用 MM 辅助函数 pxdp_get()（pmdp_get/pudp_get/p4dp_get/pgdp_get），平台可在需要时覆盖。在 arm64 上这些访问器目前默认为 READ_ONCE()，保持现有 D64 行为不变，但为将来以原子方式读取 128 位页表项（D128 使能）做准备。</p><blockquote><p><strong>学习价值</strong>：封面信清晰阐述了为何需要专用页表访问器，是学习内核 API 演进与硬件适配策略的优质案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（14 条）</li><li><strong>网络</strong>（2 条）</li><li><strong>Rust in Linux</strong>（11 条）</li><li><strong>跟踪与性能</strong>（2 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（10 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="ca9e280e6f61-·-amd-rocm-hrx-s-loom-0-2-expands-c-support-improved-targeting" tabindex="-1"><code>ca9e280e6f61</code> · <a href="https://www.phoronix.com/news/HRX-Loom-0.2" target="_blank" rel="noreferrer">AMD ROCm HRX&#39;s Loom 0.2 Expands C++ Support, Improved Targeting</a> <a class="header-anchor" href="#ca9e280e6f61-·-amd-rocm-hrx-s-loom-0-2-expands-c-support-improved-targeting" aria-label="Permalink to &quot;`ca9e280e6f61` · [AMD ROCm HRX&#39;s Loom 0.2 Expands C++ Support, Improved Targeting](https://www.phoronix.com/news/HRX-Loom-0.2)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD ROCm 的 HRX Loom 发布新版本 0.2，它是支持 AI agent 工作流的编译器、运行时和服务基础设施，本次更新扩展了 C++ 支持并改进了目标平台适配能力。</p><blockquote><p><strong>学习价值</strong>：属于 AI 编译器生态新闻，与 Linux 内核开发无直接关系，对内核学习者价值较低。</p></blockquote><h3 id="ced93c468ff3-·-mrdimm-8800-mt-s-vs-12800-mt-s-memory-performance-with-amd-epyc-venice" tabindex="-1"><code>ced93c468ff3</code> · <a href="https://www.phoronix.com/review/mrdimm-8800-12800-amd-epyc" target="_blank" rel="noreferrer">MRDIMM 8800 MT/s vs. 12800 MT/s Memory Performance With AMD EPYC Venice</a> <a class="header-anchor" href="#ced93c468ff3-·-mrdimm-8800-mt-s-vs-12800-mt-s-memory-performance-with-amd-epyc-venice" aria-label="Permalink to &quot;`ced93c468ff3` · [MRDIMM 8800 MT/s vs. 12800 MT/s Memory Performance With AMD EPYC Venice](https://www.phoronix.com/review/mrdimm-8800-12800-amd-epyc)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>随着 AMD EPYC 9006 SP7 上市及 EPYC 9686F、EPYC 9996 处理器评测发布，MRDIMM-12800 内存对 Zen 6 服务器处理器的影响成为热门话题。Phoronix 对 EPYC 9686F 双路系统分别在 8800 MT/s 和 12800 MT/s 内存频率下进行了对比测试。</p><blockquote><p><strong>学习价值</strong>：服务器内存子系统性能基准测试，有助于理解 MRDIMM 带宽对实际负载的影响，但属于硬件评测而非内核开发内容。</p></blockquote><h3 id="a406528c27b6-·-patch-v4-2-2-mm-ksm-add-initialization-helpers-for-scan-get-next-rmap-item" tabindex="-1"><code>a406528c27b6</code> · <a href="https://lore.kernel.org/all/20261117015225.618954-1-xu.xin@linux.dev/" target="_blank" rel="noreferrer">[PATCH v4 2/2] mm/ksm: add initialization helpers for scan_get_next_rmap_item()</a> <a class="header-anchor" href="#a406528c27b6-·-patch-v4-2-2-mm-ksm-add-initialization-helpers-for-scan-get-next-rmap-item" aria-label="Permalink to &quot;`a406528c27b6` · [[PATCH v4 2/2] mm/ksm: add initialization helpers for scan_get_next_rmap_item()](https://lore.kernel.org/all/20261117015225.618954-1-xu.xin@linux.dev/)&quot;">​</a></h3><p><em>Xu Xin (vivo) (xu.xin@linux.dev)｜lkml</em></p><p>该补丁将新扫描周期的检查逻辑提取为 scan_should_start_new_cycle()，并新增 scan_get_first_mm() 辅助函数将扫描游标推进到第一个 mm_slot，保持原有执行顺序不变，使 scan_get_next_rmap_item() 更清晰易读。属于无功能变更的代码清理，已获 Lorenzo Stoakes 和 David Hildenbrand 的 Reviewed-by。</p><blockquote><p><strong>学习价值</strong>：展示了 KSM 扫描循环的内部结构，是理解 KSM 内存去重机制和大型函数重构手法的良好材料。</p></blockquote><h3 id="_009c420d3597-·-patch-v4-1-2-mm-ksm-extract-helper-functions-for-scan-cycle-cleanup" tabindex="-1"><code>009c420d3597</code> · <a href="https://lore.kernel.org/all/20261117015138.612340-1-xu.xin@linux.dev/" target="_blank" rel="noreferrer">[PATCH v4 1/2] mm/ksm: extract helper functions for scan cycle cleanup</a> <a class="header-anchor" href="#_009c420d3597-·-patch-v4-1-2-mm-ksm-extract-helper-functions-for-scan-cycle-cleanup" aria-label="Permalink to &quot;`009c420d3597` · [[PATCH v4 1/2] mm/ksm: extract helper functions for scan cycle cleanup](https://lore.kernel.org/all/20261117015138.612340-1-xu.xin@linux.dev/)&quot;">​</a></h3><p><em>Xu Xin (vivo) (xu.xin@linux.dev)｜lkml</em></p><p>由于 scan_get_next_rmap_item() 过于庞大，该补丁提取出 ksm_prune_migrate_nodes() 和 ksm_reset_unstable_trees() 两个辅助函数，以降低缩进层级、隔离局部变量并提升主扫描循环的可读性。同样是无功能变更的重构，已获 Reviewed-by 和 Acked-by。</p><blockquote><p><strong>学习价值</strong>：典型的内核代码重构实践，帮助学习者理解 KSM 中 stable_node 迁移剪枝和 unstable tree 重置的清理逻辑。</p></blockquote><h3 id="d7f82be63084-·-patch-v4-0-2-mm-ksm-clean-up-scan-get-next-rmap-item-initialization" tabindex="-1"><code>d7f82be63084</code> · <a href="https://lore.kernel.org/all/20261117015009.611551-1-xu.xin@linux.dev/" target="_blank" rel="noreferrer">[PATCH v4 0/2] mm/ksm: clean up scan_get_next_rmap_item() initialization</a> <a class="header-anchor" href="#d7f82be63084-·-patch-v4-0-2-mm-ksm-clean-up-scan-get-next-rmap-item-initialization" aria-label="Permalink to &quot;`d7f82be63084` · [[PATCH v4 0/2] mm/ksm: clean up scan_get_next_rmap_item() initialization](https://lore.kernel.org/all/20261117015009.611551-1-xu.xin@linux.dev/)&quot;">​</a></h3><p><em>Xu Xin (vivo) (xu.xin@linux.dev)｜lkml</em></p><p>本系列（共 2 个补丁）旨在清理 mm/ksm.c 中过于庞大复杂的 scan_get_next_rmap_item()，提取 stale stable_node 剪枝和周期初始化等公共逻辑为独立辅助函数。作者表示这是为后续引入 only-merge-zero-page 等新特性做准备，避免继续增加该函数复杂度或触碰 rmap_item 结构。</p><blockquote><p><strong>学习价值</strong>：展示了内核开发中&quot;先重构再添加新特性&quot;的工程实践，以及补丁系列的 cover letter 写作方式，对学习 KSM 和内核开发流程都有价值。</p></blockquote><h3 id="_9253c4f7ee89-·-patch-v2-0-4-arm64-add-pud-thp-support-for-dax-and-pfnmap-1" tabindex="-1"><code>9253c4f7ee89</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-1-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 0/4] arm64: Add PUD THP support for DAX and pfnmap</a> <a class="header-anchor" href="#_9253c4f7ee89-·-patch-v2-0-4-arm64-add-pud-thp-support-for-dax-and-pfnmap-1" aria-label="Permalink to &quot;`9253c4f7ee89` · [[PATCH v2 0/4] arm64: Add PUD THP support for DAX and pfnmap](https://lore.kernel.org/all/20261117020237.4037980-1-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm</em></p><p>该补丁系列为 arm64 添加 PUD 级别透明大页（THP）支持，使 DAX 和 pfnmap 场景可使用 1GB 级别的大页映射。系列包括将 x86 和 riscv 中相同的 pudp_invalidate() 实现移到通用位置、简化 pmd_special/pmd_mkspecial、添加 spurious PUD fault 修复及 PUD 页表辅助函数并选中 HAVE_ARCH_TRANSPARENT_HUGEPAGE_PUD。</p><blockquote><p><strong>学习价值</strong>：深入涉及 arm64 页表层次、THP、DAX 与 pfnmap 的交互，是学习架构级 mm 特性实现的高质量材料。</p></blockquote><h3 id="aadacceaf4b2-·-patch-v2-4-4-arm64-add-pud-thp-support-for-dax-and-pfnmap" tabindex="-1"><code>aadacceaf4b2</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-5-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 4/4] arm64: Add PUD THP support for DAX and pfnmap</a> <a class="header-anchor" href="#aadacceaf4b2-·-patch-v2-4-4-arm64-add-pud-thp-support-for-dax-and-pfnmap" aria-label="Permalink to &quot;`aadacceaf4b2` · [[PATCH v2 4/4] arm64: Add PUD THP support for DAX and pfnmap](https://lore.kernel.org/all/20261117020237.4037980-5-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm</em></p><p>该补丁为 arm64 添加处理 PUD THP 所需的页表函数，从而为 DAX 和 pfnmap 启用 PUD 级别大页。作者在开启 CONFIG_DEBUG_VM_PGTABLE 和 CONFIG_PAGE_TABLE_CHECK 的情况下，通过测试驱动在 huge_fault 回调中调用 vmf_insert_pfn_pud() 验证了页表建立及用户态读写均正确。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 DEBUG_VM_PGTABLE、PAGE_TABLE_CHECK 等调试配置和自定义测试驱动验证页表改动，是学习 arm64 页表代码与验证方法论的好范例。</p></blockquote><h3 id="_328b95ff8a67-·-patch-v2-1-4-mm-define-generic-pudp-invalidate-implementation" tabindex="-1"><code>328b95ff8a67</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-2-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 1/4] mm: define generic pudp_invalidate() implementation</a> <a class="header-anchor" href="#_328b95ff8a67-·-patch-v2-1-4-mm-define-generic-pudp-invalidate-implementation" aria-label="Permalink to &quot;`328b95ff8a67` · [[PATCH v2 1/4] mm: define generic pudp_invalidate() implementation](https://lore.kernel.org/all/20261117020237.4037980-2-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm</em></p><p>x86 和 riscv 上 pudp_invalidate() 的实现完全相同，本补丁将其移到 mm/pgtable-generic.c 作为通用实现，并使用 __HAVE_ARCH_PUDP_INVALIDATE 作为架构覆盖保护。PowerPC 保留自己的实现，后续补丁中 arm64 也将改用通用实现。无功能性变化。</p><blockquote><p><strong>学习价值</strong>：展示了内核中如何通过 _<em>HAVE_ARCH</em>* 宏将重复的架构代码收敛到通用层，是学习页表抽象层设计的良好范例。</p></blockquote><h3 id="_43ec674afb6b-·-patch-v2-3-4-mm-add-spurious-fault-fixing-support-for-huge-pud" tabindex="-1"><code>43ec674afb6b</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-4-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 3/4] mm: add spurious fault fixing support for huge pud</a> <a class="header-anchor" href="#_43ec674afb6b-·-patch-v2-3-4-mm-add-spurious-fault-fixing-support-for-huge-pud" aria-label="Permalink to &quot;`43ec674afb6b` · [[PATCH v2 3/4] mm: add spurious fault fixing support for huge pud](https://lore.kernel.org/all/20261117020237.4037980-4-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm</em></p><p>内核目前支持 PTE 和 huge PMD 映射的 spurious fault 修复，但不支持 huge PUD 映射。本补丁为 huge PUD 添加 spurious fault 修复支持，因为 arm64 的写保护 fault 只刷新本地 TLB，可能留下过期的只读 TLB 项。这是后续为 arm64 上 DAX 和 pfnmap 添加 PUD THP 支持的前置工作。</p><blockquote><p><strong>学习价值</strong>：深入讲解 spurious fault 处理机制与 TLB 刷新语义，对理解 arm64 大页映射与 TLB 一致性问题非常有价值。</p></blockquote><h3 id="aaff4f80f9b0-·-patch-v2-2-4-arm64-simplify-pmd-special-and-pmd-mkspecial" tabindex="-1"><code>aaff4f80f9b0</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-3-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 2/4] arm64: simplify pmd_special and pmd_mkspecial</a> <a class="header-anchor" href="#aaff4f80f9b0-·-patch-v2-2-4-arm64-simplify-pmd-special-and-pmd-mkspecial" aria-label="Permalink to &quot;`aaff4f80f9b0` · [[PATCH v2 2/4] arm64: simplify pmd_special and pmd_mkspecial](https://lore.kernel.org/all/20261117020237.4037980-3-tujinjiang@huawei.com/)&quot;">​</a></h3><p><em>Jinjiang Tu (<a href="mailto:tujinjiang@huawei.com" target="_blank" rel="noreferrer">tujinjiang@huawei.com</a>)｜linux-mm</em></p><p>本补丁使用 pte_special() 和 pte_mkspecial() 辅助函数简化 arm64 的 pmd_special() 和 pmd_mkspecial() 实现，并删除不再使用的 set_pmd_bit() 和 clear_pmd_bit() 辅助函数。属于纯代码清理，无功能变化。</p><blockquote><p><strong>学习价值</strong>：小型清理补丁，可帮助学习者理解 arm64 页表项标志位操作的层次复用关系。</p></blockquote><h3 id="da403ace46cb-·-patch-v5-4-4-arm64-mm-use-pgdp-get-for-pgd-accesses" tabindex="-1"><code>da403ace46cb</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-5-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 4/4] arm64/mm: Use pgdp_get() for PGD accesses</a> <a class="header-anchor" href="#da403ace46cb-·-patch-v5-4-4-arm64-mm-use-pgdp-get-for-pgd-accesses" aria-label="Permalink to &quot;`da403ace46cb` · [[PATCH V5 4/4] arm64/mm: Use pgdp_get() for PGD accesses](https://lore.kernel.org/all/20261117012758.3814093-5-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm</em></p><p>将 arm64 PGD 访问中的 READ_ONCE() 替换为 pgdp_get()，为同时支持 D64 和 D128 翻译表格式做准备。READ_ONCE() 无法为 128 位页表项提供所需的单拷贝原子性，而扩展 READ_ONCE() 支持宽于 64 位的访问被认为不妥，因为它是通用 API，可能诱发其他不当的 128 位使用者。</p><blockquote><p><strong>学习价值</strong>：展示了为硬件演进（FEAT_D128）重构 API 的典型思路，帮助理解 READ_ONCE() 的原子性边界与页表访问器抽象设计。</p></blockquote><h3 id="b39a194e5de8-·-patch-v5-3-4-arm64-mm-use-p4dp-get-for-p4d-accesses" tabindex="-1"><code>b39a194e5de8</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-4-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 3/4] arm64/mm: Use p4dp_get() for P4D accesses</a> <a class="header-anchor" href="#b39a194e5de8-·-patch-v5-3-4-arm64-mm-use-p4dp-get-for-p4d-accesses" aria-label="Permalink to &quot;`b39a194e5de8` · [[PATCH V5 3/4] arm64/mm: Use p4dp_get() for P4D accesses](https://lore.kernel.org/all/20261117012758.3814093-4-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm</em></p><p>将 arm64 P4D 访问中的 READ_ONCE() 替换为 p4dp_get()，为 D64 和 D128 翻译表格式的双支持做准备。原因是 READ_ONCE() 无法为 128 位页表项提供单拷贝原子性，且不宜为通用 API 扩展 128 位访问支持。</p><blockquote><p><strong>学习价值</strong>：与系列其他补丁一起展示了按页表级别引入专用访问器的系统性重构方法。</p></blockquote><h3 id="_56a29f509c04-·-patch-v5-2-4-arm64-mm-use-pudp-get-for-pud-accesses" tabindex="-1"><code>56a29f509c04</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-3-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 2/4] arm64/mm: Use pudp_get() for PUD accesses</a> <a class="header-anchor" href="#_56a29f509c04-·-patch-v5-2-4-arm64-mm-use-pudp-get-for-pud-accesses" aria-label="Permalink to &quot;`56a29f509c04` · [[PATCH V5 2/4] arm64/mm: Use pudp_get() for PUD accesses](https://lore.kernel.org/all/20261117012758.3814093-3-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm</em></p><p>将 arm64 PUD 访问中的 READ_ONCE() 替换为 pudp_get()，为 D64 和 D128 翻译表格式的双支持做准备。READ_ONCE() 无法为 128 位页表项提供单拷贝原子性，因此改用级别专用的访问器以便后续覆盖。</p><blockquote><p><strong>学习价值</strong>：是理解页表访问器分层设计与 128 位原子访问问题的好材料。</p></blockquote><h3 id="d4dce944bdcb-·-patch-v5-1-4-arm64-mm-use-pmdp-get-for-pmd-accesses" tabindex="-1"><code>d4dce944bdcb</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-2-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 1/4] arm64/mm: Use pmdp_get() for PMD accesses</a> <a class="header-anchor" href="#d4dce944bdcb-·-patch-v5-1-4-arm64-mm-use-pmdp-get-for-pmd-accesses" aria-label="Permalink to &quot;`d4dce944bdcb` · [[PATCH V5 1/4] arm64/mm: Use pmdp_get() for PMD accesses](https://lore.kernel.org/all/20261117012758.3814093-2-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm</em></p><p>将 arm64 PMD 访问中的 READ_ONCE() 替换为 pmdp_get()，为 D64 和 D128 翻译表格式的双支持做准备。READ_ONCE() 无法为 128 位页表项提供单拷贝原子性，改用级别专用访问器为后续 D128 使能铺路。</p><blockquote><p><strong>学习价值</strong>：系列重构的第一步，帮助学习者跟踪 arm64 页表访问从 READ_ONCE() 到专用访问器的演进过程。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_1bc264edce5d-·-patch-v5-0-4-arm64-mm-convert-pgtable-read-once-as-pxdp-get-1" tabindex="-1"><code>1bc264edce5d</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-1-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 0/4] arm64/mm: Convert pgtable READ_ONCE() as pxdp_get()</a> <a class="header-anchor" href="#_1bc264edce5d-·-patch-v5-0-4-arm64-mm-convert-pgtable-read-once-as-pxdp-get-1" aria-label="Permalink to &quot;`1bc264edce5d` · [[PATCH V5 0/4] arm64/mm: Convert pgtable READ_ONCE() as pxdp_get()](https://lore.kernel.org/all/20261117012758.3814093-1-anshuman.khandual@arm.com/)&quot;">​</a></h3><p><em>Anshuman Khandual (<a href="mailto:anshuman.khandual@arm.com" target="_blank" rel="noreferrer">anshuman.khandual@arm.com</a>)｜linux-mm</em></p><p>本系列将页表项的 READ_ONCE() 访问统一改经级别专用的通用 MM 辅助函数 pxdp_get()（pmdp_get/pudp_get/p4dp_get/pgdp_get），平台可在需要时覆盖。在 arm64 上这些访问器目前默认为 READ_ONCE()，保持现有 D64 行为不变，但为将来以原子方式读取 128 位页表项（D128 使能）做准备。</p><blockquote><p><strong>学习价值</strong>：封面信清晰阐述了为何需要专用页表访问器，是学习内核 API 演进与硬件适配策略的优质案例。</p></blockquote><h3 id="df280c8b3c9a-·-patch-net-vsock-only-undo-ss-connecting-when-connect-fails" tabindex="-1"><code>df280c8b3c9a</code> · <a href="https://lore.kernel.org/all/20261116-vsock-connect-close-v1-1-43fb125973dd@meta.com/" target="_blank" rel="noreferrer">[PATCH net] vsock: only undo SS_CONNECTING when connect() fails</a> <a class="header-anchor" href="#df280c8b3c9a-·-patch-net-vsock-only-undo-ss-connecting-when-connect-fails" aria-label="Permalink to &quot;`df280c8b3c9a` · [[PATCH net] vsock: only undo SS_CONNECTING when connect() fails](https://lore.kernel.org/all/20261116-vsock-connect-close-v1-1-43fb125973dd@meta.com/)&quot;">​</a></h3><p><em>Bobby Eshleman (<a href="mailto:bobbyeshleman@meta.com" target="_blank" rel="noreferrer">bobbyeshleman@meta.com</a>)｜netdev</em></p><p>vsock_connect() 在持锁睡眠期间，transport 可能完成握手将 socket 置为 SS_CONNECTED 后又重置连接；connect() 重新获得锁后发现 sk_err 被设置，会把 socket 错误地移回 SS_UNCONNECTED。修复方案是仅在 socket 仍处于 SS_CONNECTING 状态时才回退状态，避免后续 connect() 到其他 transport 时释放已连接的 transport。</p><blockquote><p><strong>学习价值</strong>：典型的并发状态机竞态修复案例，对学习 socket 锁保护下的状态转换与 vsock transport 生命周期管理很有帮助。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_9749e0c012fd-·-rust-nightly-to-begin-enabling-parallel-frontend-by-default" tabindex="-1"><code>9749e0c012fd</code> · <a href="https://www.phoronix.com/news/Rust-Nightly-Parallel-Frontend" target="_blank" rel="noreferrer">Rust Nightly To Begin Enabling Parallel Frontend By Default</a> <a class="header-anchor" href="#_9749e0c012fd-·-rust-nightly-to-begin-enabling-parallel-frontend-by-default" aria-label="Permalink to &quot;`9749e0c012fd` · [Rust Nightly To Begin Enabling Parallel Frontend By Default](https://www.phoronix.com/news/Rust-Nightly-Parallel-Frontend)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Rust 编译器的后端早已支持多线程编译，但前端一直默认串行执行。如今 Rust Nightly 开始默认启用并行前端，以便在最终稳定化之前进行更充分的测试。</p><blockquote><p><strong>学习价值</strong>：对关注 Rust in Linux 的学习者而言，了解 Rust 工具链（尤其是编译器并行化）的进展有助于理解内核 Rust 代码的构建环境演进。</p></blockquote><h3 id="_455ec4239ac4-·-patch-v3-5-5-rust-sync-condvar-add-non-exclusive-freezable-waiting" tabindex="-1"><code>455ec4239ac4</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-6-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 5/5] rust: sync: condvar: add non-exclusive freezable waiting</a> <a class="header-anchor" href="#_455ec4239ac4-·-patch-v3-5-5-rust-sync-condvar-add-non-exclusive-freezable-waiting" aria-label="Permalink to &quot;`455ec4239ac4` · [[PATCH v3 5/5] rust: sync: condvar: add non-exclusive freezable waiting](https://lore.kernel.org/all/20261117001507.1611984-6-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>Rust 内核的 CondVar 目前将所有睡眠任务注册为 exclusive waiter。本补丁新增 wait_interruptible_freezable_nonexclusive()，基于 WaitQueue::wait_once() 实现非独占等待，并说明 notify_one() 和 notify_sync() 也会唤醒所有非独占 waiter。该支持是为后续 Binder 驱动转换到 Rust CondVar 做准备。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust in Linux 中同步原语如何对齐 C 内核的 wait queue 语义，是跟踪 Rust 内核抽象演进的实用参考。</p></blockquote><h3 id="_0139bb6344a8-·-patch-v3-4-5-rust-sync-condvar-use-task-schedule-timeout" tabindex="-1"><code>0139bb6344a8</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-5-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 4/5] rust: sync: condvar: use task::schedule_timeout()</a> <a class="header-anchor" href="#_0139bb6344a8-·-patch-v3-4-5-rust-sync-condvar-use-task-schedule-timeout" aria-label="Permalink to &quot;`0139bb6344a8` · [[PATCH v3 4/5] rust: sync: condvar: use task::schedule_timeout()](https://lore.kernel.org/all/20261117001507.1611984-5-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>该补丁将 CondVar::wait_internal() 从直接调用 bindings::schedule_timeout() 改为使用安全的 task::schedule_timeout() 封装，从而移除 CondVar 中的 unsafe 调用。这是 WaitQueue 系列的第 4 个补丁。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核抽象中逐步消除 unsafe 边界代码的典型重构方式，对理解 safe wrapper 设计很有参考价值。</p></blockquote><h3 id="_100a8b86ca5d-·-patch-v3-3-5-rust-sync-convert-condvar-and-pollcondvar-to-use-waitqueue" tabindex="-1"><code>100a8b86ca5d</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-4-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 3/5] rust: sync: convert CondVar and PollCondVar to use WaitQueue</a> <a class="header-anchor" href="#_100a8b86ca5d-·-patch-v3-3-5-rust-sync-convert-condvar-and-pollcondvar-to-use-waitqueue" aria-label="Permalink to &quot;`100a8b86ca5d` · [[PATCH v3 3/5] rust: sync: convert CondVar and PollCondVar to use WaitQueue](https://lore.kernel.org/all/20261117001507.1611984-4-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>将 CondVar 和 PollCondVar 从直接封装原始 wait_queue_head 改为基于新的 WaitQueue 抽象，消除重复的初始化、pinning、Send/Sync 和唤醒代码。等待逻辑仍保留在 CondVar 中，因为需要在睡眠前后释放和重新获取锁，通过 wait_once_exclusive() 实现带锁感知的睡眠。</p><blockquote><p><strong>学习价值</strong>：很好地演示了 Rust 抽象层如何复用基础设施，同时解释了为何某些逻辑无法泛化（锁保护跨越睡眠点）的深层原因。</p></blockquote><h3 id="_027ab8d1ad07-·-patch-v3-2-5-rust-sync-add-waitqueue-infrastructure" tabindex="-1"><code>027ab8d1ad07</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-3-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 2/5] rust: sync: add WaitQueue infrastructure</a> <a class="header-anchor" href="#_027ab8d1ad07-·-patch-v3-2-5-rust-sync-add-waitqueue-infrastructure" aria-label="Permalink to &quot;`027ab8d1ad07` · [[PATCH v3 2/5] rust: sync: add WaitQueue infrastructure](https://lore.kernel.org/all/20261117001507.1611984-3-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>新增 WaitQueue 抽象，封装内核的 struct wait_queue_head，提供接受条件闭包的 wait_event() 系列方法，API 镜像 C 语言的 wait_event() 家族（含 interruptible、timeout 变体及 wake_up() 等）。错误类型映射到 ERESTARTSYS 和 ETIMEDOUT。</p><blockquote><p><strong>学习价值</strong>：是学习 C wait queue 机制与 Rust 安全抽象如何对应的优秀范例，尤其适合对比 C 宏与 Rust 闭包两种实现风格。</p></blockquote><h3 id="_84ca6c48d56a-·-patch-v3-1-5-rust-task-add-safe-schedule-timeout-wrapper" tabindex="-1"><code>84ca6c48d56a</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-2-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 1/5] rust: task: add safe schedule_timeout() wrapper</a> <a class="header-anchor" href="#_84ca6c48d56a-·-patch-v3-1-5-rust-task-add-safe-schedule-timeout-wrapper" aria-label="Permalink to &quot;`84ca6c48d56a` · [[PATCH v3 1/5] rust: task: add safe schedule_timeout() wrapper](https://lore.kernel.org/all/20261117001507.1611984-2-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>为 schedule_timeout() 添加安全封装，接受并返回 Delta&lt;Jiffy&gt; 类型，负时长按零处理。这是 WaitQueue 系列的基础补丁。</p><blockquote><p><strong>学习价值</strong>：体现了 Rust 内核中时间类型（Delta/Jiffy）如何用于构建类型安全的调度接口，是小型 safe wrapper 的简洁示例。</p></blockquote><h3 id="a58e6cf40d19-·-patch-v3-0-5-rust-sync-add-waitqueue-infrastructure-1" tabindex="-1"><code>a58e6cf40d19</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 0/5] rust: sync: add WaitQueue infrastructure</a> <a class="header-anchor" href="#a58e6cf40d19-·-patch-v3-0-5-rust-sync-add-waitqueue-infrastructure-1" aria-label="Permalink to &quot;`a58e6cf40d19` · [[PATCH v3 0/5] rust: sync: add WaitQueue infrastructure](https://lore.kernel.org/all/20261117001507.1611984-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>本系列新增封装 struct wait_queue_head 的 WaitQueue 抽象，提供接受条件闭包的 wait_event() 风格方法。动机来自后续 DRM 补丁（驱动 unbind 时等待 in-flight 文件关闭操作）以及 Tyr 驱动的 CSF firmware 响应等待需求，同时将 CondVar 转换为基于 WaitQueue 实现并去除重复代码。</p><blockquote><p><strong>学习价值</strong>：展示了内核抽象 API 的设计如何由真实驱动需求驱动，cover letter 中对动机和依赖关系的说明对理解补丁系列组织方式很有帮助。</p></blockquote><h3 id="d66e01794da3-·-patch-2-2-rust-sync-atomic-fix-typo-in-safety-comment-for-isize" tabindex="-1"><code>d66e01794da3</code> · <a href="https://lore.kernel.org/all/20261116195011.24156-2-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH 2/2] rust: sync: atomic: Fix typo in SAFETY comment for <code>isize</code></a> <a class="header-anchor" href="#d66e01794da3-·-patch-2-2-rust-sync-atomic-fix-typo-in-safety-comment-for-isize" aria-label="Permalink to &quot;`d66e01794da3` · [[PATCH 2/2] rust: sync: atomic: Fix typo in SAFETY comment for `isize`](https://lore.kernel.org/all/20261116195011.24156-2-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>修复 rust/kernel/sync/atomic/predefine.rs 中 AtomicAdd&lt;isize&gt; 实现的 SAFETY 注释笔误：原文误写为 usize，改为正确的 isize。</p><blockquote><p><strong>学习价值</strong>：虽是微小文档修正，但提醒学习者 SAFETY 注释的准确性对 unsafe Rust 代码审查至关重要。</p></blockquote><h3 id="_446145374afa-·-patch-1-2-rust-sync-atomic-update-safety-requirements-for-atomicadd" tabindex="-1"><code>446145374afa</code> · <a href="https://lore.kernel.org/all/20261116195011.24156-1-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH 1/2] rust: sync: atomic: Update safety requirements for <code>AtomicAdd</code></a> <a class="header-anchor" href="#_446145374afa-·-patch-1-2-rust-sync-atomic-update-safety-requirements-for-atomicadd" aria-label="Permalink to &quot;`446145374afa` · [[PATCH 1/2] rust: sync: atomic: Update safety requirements for `AtomicAdd`](https://lore.kernel.org/all/20261116195011.24156-1-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>更新 AtomicAdd trait 的 # Safety 注释：移除未解决的 TODO，修复断裂的语句，并明确将语义定义为 wrapping 二进制补码加法（v.wrapping_add(delta)），准确反映底层整数原语的行为。</p><blockquote><p><strong>学习价值</strong>：说明安全契约文档必须与实际语义精确对齐，是理解 Rust 原子操作抽象安全要求的好例子。</p></blockquote><h3 id="_973c267dbc46-·-patch-v22-5-5-rust-add-ownableintoshared-and-ownabletryfromshared" tabindex="-1"><code>973c267dbc46</code> · <a href="https://lore.kernel.org/all/20261116-unique-ref-v22-5-12029383206d@kernel.org/" target="_blank" rel="noreferrer">[PATCH v22 5/5] rust: Add <code>OwnableIntoShared</code> and <code>OwnableTryFromShared</code></a> <a class="header-anchor" href="#_973c267dbc46-·-patch-v22-5-5-rust-add-ownableintoshared-and-ownabletryfromshared" aria-label="Permalink to &quot;`973c267dbc46` · [[PATCH v22 5/5] rust: Add `OwnableIntoShared` and `OwnableTryFromShared`](https://lore.kernel.org/all/20261116-unique-ref-v22-5-12029383206d@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>新增 OwnableIntoShared 和 OwnableTryFromShared trait，实现 ARef&lt;T&gt; 与 Owned&lt;T&gt; 之间的安全转换。前者提供从 Owned 到 ARef 的不可失败转换，后者提供从 ARef 回到 Owned 的可失败转换，仅当对象不存在其他 Owned&lt;T&gt; 且满足创建条件时成功。</p><blockquote><p><strong>学习价值</strong>：深入展示了 Rust 类型系统如何用 trait 编码所有权与引用共存约束，对理解内核对象生命周期建模极具启发性。</p></blockquote><h3 id="b75a2965c720-·-patch-v22-0-5-rust-add-ownable-trait-and-owned-type-1" tabindex="-1"><code>b75a2965c720</code> · <a href="https://lore.kernel.org/all/20261116-unique-ref-v22-0-12029383206d@kernel.org/" target="_blank" rel="noreferrer">[PATCH v22 0/5] rust: add <code>Ownable</code> trait and <code>Owned</code> type</a> <a class="header-anchor" href="#b75a2965c720-·-patch-v22-0-5-rust-add-ownable-trait-and-owned-type-1" aria-label="Permalink to &quot;`b75a2965c720` · [[PATCH v22 0/5] rust: add `Ownable` trait and `Owned` type](https://lore.kernel.org/all/20261116-unique-ref-v22-0-12029383206d@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>本系列新增 Ownable trait 和 Owned 类型，用于自定义分配和销毁方式的类型（尤其适用于 C 侧类型），保证任一时刻最多存在一个 Owned&lt;T&gt;。同时将 RefCounted trait 从 AlwaysRefCounted 中拆分，使类型可与 ARef 配合而不允许 &amp;T 到 ARef&lt;T&gt; 的转换，并为 Owned 实现 ForeignOwnable。</p><blockquote><p><strong>学习价值</strong>：是研究 Rust 内核引用计数与所有权模型演进的优秀材料，trait 拆分决策体现了 API 设计的权衡思路。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_6103aefdd888-·-intel-talks-up-gpu-d270-performance-open-source-software-support" tabindex="-1"><code>6103aefdd888</code> · <a href="https://www.phoronix.com/news/Intel-GPU-270-Open-Performance" target="_blank" rel="noreferrer">Intel Talks Up GPU D270 Performance &amp; Open-Source Software Support</a> <a class="header-anchor" href="#_6103aefdd888-·-intel-talks-up-gpu-d270-performance-open-source-software-support" aria-label="Permalink to &quot;`6103aefdd888` · [Intel Talks Up GPU D270 Performance &amp; Open-Source Software Support](https://www.phoronix.com/news/Intel-GPU-270-Open-Performance)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>在 Supercomputing 2026 周期间，Intel 发布博客宣传其基于 Xe3P 架构的 Intel GPU D 系列 &quot;Crescent Island&quot; 硬件，重点介绍了 GPU D270 的性能表现及开源软件支持情况。</p><blockquote><p><strong>学习价值</strong>：涉及 GPU 硬件与开源驱动生态，对关注 DRM/图形子系统或异构计算的学习者有一定参考价值。</p></blockquote><h3 id="c4dab9cae5fc-·-gnu-s-gawk-5-4-2-released-with-big-performance-improvement" tabindex="-1"><code>c4dab9cae5fc</code> · <a href="https://www.phoronix.com/news/GNU-Gawk-5.4.2" target="_blank" rel="noreferrer">GNU&#39;s Gawk 5.4.2 Released With Big Performance Improvement</a> <a class="header-anchor" href="#c4dab9cae5fc-·-gnu-s-gawk-5-4-2-released-with-big-performance-improvement" aria-label="Permalink to &quot;`c4dab9cae5fc` · [GNU&#39;s Gawk 5.4.2 Released With Big Performance Improvement](https://www.phoronix.com/news/GNU-Gawk-5.4.2)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>GNU 的 AWK 语言实现 Gawk 发布新版本 5.4.2，这一常用于数据提取、模式匹配和数据处理的工具带来了显著的性能改进。</p><blockquote><p><strong>学习价值</strong>：Gawk 是内核开发者常用的文本处理工具，性能改进对日常开发工作流有实际帮助，但与内核本身无关。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="c59652ab525f-·-next-20261116-linux-next" tabindex="-1"><code>c59652ab525f</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261116-2026-11-16" target="_blank" rel="noreferrer">next-20261116: linux-next</a> <a class="header-anchor" href="#c59652ab525f-·-next-20261116-linux-next" aria-label="Permalink to &quot;`c59652ab525f` · [next-20261116: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261116-2026-11-16)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 16 日发布 next-20261116 版本，供集成测试下一合并窗口的内容。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 发布是了解即将进入主线的新特性和子系统动态的日常习惯。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_11598d36da13-·-a-new-generation-of-futexes-1" tabindex="-1"><code>11598d36da13</code> · <a href="https://lwn.net/Articles/1102988/" target="_blank" rel="noreferrer">[$] A new generation of futexes</a> <a class="header-anchor" href="#_11598d36da13-·-a-new-generation-of-futexes-1" aria-label="Permalink to &quot;`11598d36da13` · [[$] A new generation of futexes](https://lwn.net/Articles/1102988/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>futex 是内核中为用户空间快速 mutex 提供支持的子系统，但其性能仍不能满足部分用户需求，且多年来实现日趋复杂，目前存在两种基本变体。Suleiman Souhlal 发布了新的补丁系列，引入第三种 futex 类别 &quot;futex PING&quot;（priority inheritance next generation），以追求更快的 futex 性能。</p><blockquote><p><strong>学习价值</strong>：futex 是理解用户空间同步原语与内核交互的经典案例，本文展示了同步子系统演进中性能与复杂度的权衡，对学习内核锁机制很有价值。</p></blockquote><h3 id="_62e6f4e99e58-·-manjaro-project-e-v-non-profit-organization-created" tabindex="-1"><code>62e6f4e99e58</code> · <a href="https://lwn.net/Articles/1107814/" target="_blank" rel="noreferrer">Manjaro Project e.V. non-profit organization created</a> <a class="header-anchor" href="#_62e6f4e99e58-·-manjaro-project-e-v-non-profit-organization-created" aria-label="Permalink to &quot;`62e6f4e99e58` · [Manjaro Project e.V. non-profit organization created](https://lwn.net/Articles/1107814/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Frank Vandermeiren 宣布成立 Manjaro Project e.V.，这是一个位于德国的非营利组织，独立于 Manjaro GmbH &amp; Co KG 公司。此举源于今年早些时候 Manjaro Linux 贡献者与项目负责人兼公司 CEO Philip Müller 之间的治理权之争。新组织目前仍在优化开发基础设施，部分原因是旧基础设施持续遭受 AI 机器人攻击。</p><blockquote><p><strong>学习价值</strong>：属于发行版社区治理新闻，与内核技术本身关联不大，对内核学习者参考价值有限。</p></blockquote><h3 id="d9ed11bb102d-·-security-updates-for-monday" tabindex="-1"><code>d9ed11bb102d</code> · <a href="https://lwn.net/Articles/1107811/" target="_blank" rel="noreferrer">Security updates for Monday</a> <a class="header-anchor" href="#d9ed11bb102d-·-security-updates-for-monday" aria-label="Permalink to &quot;`d9ed11bb102d` · [Security updates for Monday](https://lwn.net/Articles/1107811/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Debian 和 Fedora 发布了例行安全更新，涉及大量软件包，包括 Debian 的 kernel、postgresql-15、pdns-recursor 等，以及 Fedora 的 firefox、dhcpcd、mysql、多个 rust 相关包等。</p><blockquote><p><strong>学习价值</strong>：常规安全更新汇总，其中包含 kernel 安全更新条目，可作为跟踪发行版内核补丁的线索，但技术深度有限。</p></blockquote><h3 id="_5e4e3a849f6f-·-kernel-prepatch-7-4-rc3" tabindex="-1"><code>5e4e3a849f6f</code> · <a href="https://lwn.net/Articles/1107606/" target="_blank" rel="noreferrer">Kernel prepatch 7.4-rc3</a> <a class="header-anchor" href="#_5e4e3a849f6f-·-kernel-prepatch-7-4-rc3" aria-label="Permalink to &quot;`5e4e3a849f6f` · [Kernel prepatch 7.4-rc3](https://lwn.net/Articles/1107606/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Linus 发布了 7.4-rc3 内核预补丁供测试。他表示本次更新看起来相当正常，以 drivers（networking 和 gpu 为主）的改动居首，补丁数量众多但大多数都很小。</p><blockquote><p><strong>学习价值</strong>：跟踪 rc 版本发布节奏有助于了解内核开发周期规律，rc3 阶段通常以小修补为主，是观察内核发布流程的窗口。</p></blockquote><h3 id="_9e899190808b-·-almalinux-10-3-released-with-modsecurity-restored-various-updates" tabindex="-1"><code>9e899190808b</code> · <a href="https://www.phoronix.com/news/AlmaLinux-10.3-Released" target="_blank" rel="noreferrer">AlmaLinux 10.3 Released With ModSecurity Restored, Various Updates</a> <a class="header-anchor" href="#_9e899190808b-·-almalinux-10-3-released-with-modsecurity-restored-various-updates" aria-label="Permalink to &quot;`9e899190808b` · [AlmaLinux 10.3 Released With ModSecurity Restored, Various Updates](https://www.phoronix.com/news/AlmaLinux-10.3-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>继 Red Hat Enterprise Linux 10.3 发布之后，AlmaLinux 10.3 也正式进入生产可用状态，同时发布的还有 AlmaLinux 9.9。新版本恢复了 ModSecurity 支持并包含各类更新。</p><blockquote><p><strong>学习价值</strong>：发行版发布新闻，可侧面了解企业级 Linux 的版本节奏，但对内核技术学习帮助不大。</p></blockquote><h3 id="_4573d918f929-·-llvm-s-old-amd-r600-compiler-backend-slated-for-removal" tabindex="-1"><code>4573d918f929</code> · <a href="https://www.phoronix.com/news/LLVM-R600-Backend-To-Retire" target="_blank" rel="noreferrer">LLVM&#39;s Old AMD R600 Compiler Backend Slated For Removal</a> <a class="header-anchor" href="#_4573d918f929-·-llvm-s-old-amd-r600-compiler-backend-slated-for-removal" aria-label="Permalink to &quot;`4573d918f929` · [LLVM&#39;s Old AMD R600 Compiler Backend Slated For Removal](https://www.phoronix.com/news/LLVM-R600-Backend-To-Retire)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>LLVM 代码库中老旧的 ATI/AMD Radeon R600 后端计划被移除，因为它已成为遗留负担，且现代 Mesa 驱动栈不再使用它。该后端主要服务于老一代 Radeon HD 显卡的 OpenCL/TGSI 编译路径。</p><blockquote><p><strong>学习价值</strong>：与 Linux 内核学习关联较弱，可作为了解开源编译器生态中遗留代码清理实践的背景阅读。</p></blockquote><h3 id="b0ee6d2825d2-·-gcc-17-might-land-native-aarch64-darwin-macos-support" tabindex="-1"><code>b0ee6d2825d2</code> · <a href="https://www.phoronix.com/news/GCC-Native-AArch64-Darwin-Patch" target="_blank" rel="noreferrer">GCC 17 Might Land Native AArch64 Darwin/macOS Support</a> <a class="header-anchor" href="#b0ee6d2825d2-·-gcc-17-might-land-native-aarch64-darwin-macos-support" aria-label="Permalink to &quot;`b0ee6d2825d2` · [GCC 17 Might Land Native AArch64 Darwin/macOS Support](https://www.phoronix.com/news/GCC-Native-AArch64-Darwin-Patch)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>自 GCC 10 时代（2020 年）开始开发的原生 AArch64 Darwin/macOS 支持，可能最终在上游 GCC 17 中落地，使 Apple Silicon 上的 macOS 用户无需依赖 LLVM Clang 即可使用 GCC。该补丁此前已在 Homebrew 和 MacPorts 的 GCC 构建中应用。</p><blockquote><p><strong>学习价值</strong>：属于编译器工具链新闻，对内核学习价值有限，仅可帮助理解不同架构下内核编译工具链的差异。</p></blockquote><h3 id="d43e9604e7a7-·-modern-ntfs-driver-gaining-o-tmpfile-support-with-linux-7-5" tabindex="-1"><code>d43e9604e7a7</code> · <a href="https://www.phoronix.com/news/Linux-7.5-NTFS-TMPFILE" target="_blank" rel="noreferrer">Modern NTFS Driver Gaining O_TMPFILE Support With Linux 7.5</a> <a class="header-anchor" href="#d43e9604e7a7-·-modern-ntfs-driver-gaining-o-tmpfile-support-with-linux-7-5" aria-label="Permalink to &quot;`d43e9604e7a7` · [Modern NTFS Driver Gaining O_TMPFILE Support With Linux 7.5](https://www.phoronix.com/news/Linux-7.5-NTFS-TMPFILE)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.2 中随 &quot;NTFS Resurrection&quot; 引入的现代 NTFS 内核读写驱动持续获得新特性，即将到来的 Linux 7.5 周期中正在排队加入 O_TMPFILE 支持，用于临时文件处理。这进一步完善了该开源 NTFS 驱动的功能覆盖。</p><blockquote><p><strong>学习价值</strong>：展示了文件系统驱动如何逐步补齐 VFS 层接口（如 O_TMPFILE）支持，是学习 fs 子系统特性演进的不错案例。</p></blockquote><h3 id="_9d772aad6a23-·-purism-aiming-to-deliver-new-librem-5-smartphone-with-risc-v-soc" tabindex="-1"><code>9d772aad6a23</code> · <a href="https://www.phoronix.com/news/Librem-5-v2-Announced" target="_blank" rel="noreferrer">Purism Aiming To Deliver New Librem 5 Smartphone With RISC-V SoC</a> <a class="header-anchor" href="#_9d772aad6a23-·-purism-aiming-to-deliver-new-librem-5-smartphone-with-risc-v-soc" aria-label="Permalink to &quot;`9d772aad6a23` · [Purism Aiming To Deliver New Librem 5 Smartphone With RISC-V SoC](https://www.phoronix.com/news/Librem-5-v2-Announced)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Purism 在经历 Librem 5 的多次延期和挑战后，宣布推出搭载 RISC-V SoC 的 Librem 5 v2 智能手机。这将是主打自由软件的手机向 RISC-V 架构迁移的重要尝试。</p><blockquote><p><strong>学习价值</strong>：硬件产品新闻，对内核学习价值较低，但可关注后续 RISC-V SoC 对主线内核支持的影响。</p></blockquote><h3 id="_18022a2d327e-·-fwupd-2-1-10-brings-fixes-new-synaptics-touchpad-supported" tabindex="-1"><code>18022a2d327e</code> · <a href="https://www.phoronix.com/news/Fwupd-2.1.10-Released" target="_blank" rel="noreferrer">Fwupd 2.1.10 Brings Fixes, New Synaptics Touchpad Supported</a> <a class="header-anchor" href="#_18022a2d327e-·-fwupd-2-1-10-brings-fixes-new-synaptics-touchpad-supported" aria-label="Permalink to &quot;`18022a2d327e` · [Fwupd 2.1.10 Brings Fixes, New Synaptics Touchpad Supported](https://www.phoronix.com/news/Fwupd-2.1.10-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Red Hat 的 Fwupd/LVFS 主开发者 Richard Hughes 发布了 Fwupd 2.1.10 稳定版，用于在 Linux 上执行固件更新。新版本带来多项修复并新增对一款 Synaptics 触摸板的支持。</p><blockquote><p><strong>学习价值</strong>：用户态固件更新工具的发布消息，与内核学习关联不大，可了解 Linux 固件更新生态的组成。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>9253c4f7ee89</code> · <a href="https://lore.kernel.org/all/20261117020237.4037980-1-tujinjiang@huawei.com/" target="_blank" rel="noreferrer">[PATCH v2 0/4] arm64: Add PUD THP support for DAX and pfnmap</a></li><li><code>a58e6cf40d19</code> · <a href="https://lore.kernel.org/all/20261117001507.1611984-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 0/5] rust: sync: add WaitQueue infrastructure</a></li><li><code>b75a2965c720</code> · <a href="https://lore.kernel.org/all/20261116-unique-ref-v22-0-12029383206d@kernel.org/" target="_blank" rel="noreferrer">[PATCH v22 0/5] rust: add <code>Ownable</code> trait and <code>Owned</code> type</a></li><li><code>1bc264edce5d</code> · <a href="https://lore.kernel.org/all/20261117012758.3814093-1-anshuman.khandual@arm.com/" target="_blank" rel="noreferrer">[PATCH V5 0/4] arm64/mm: Convert pgtable READ_ONCE() as pxdp_get()</a></li></ul>',195)])])}const h=a(n,[["render",l]]);export{m as __pageData,h as default};
